function (variables) {
	var historyGrid = new GridWidget(variables.element, variables.history);
	historyGrid.editable = false;
	historyGrid.sortable = false;
	historyGrid.filterable = false;
	historyGrid.pageable = false;
	historyGrid.scrollable = true;
	historyGrid.groupable = false;
	historyGrid.columns = [
		{ field: "UserId", type: "string", title: "[resource_shortdisplayname[UserId]]", width: 140 },
		{ field: "Message", type: "string", title: "[resource_shortdisplayname[Message]]" },
		{ field: "CreatedOn", type: "date", title: "[resource_shortdisplayname[CreatedOn]]", format: "{0:" + type.dateFormat + " H:mm:ss}", width: 150 }
	];
	variables.HistoryGrid = historyGrid;
	return historyGrid;
}
